export class DynamicConfig {
  private static config = new Map<string, any>();

  static async initializeWatcher(consul: ConsulClient) {
    const watch = consul.watch({
      method: consul.kv.get,
      options: { key: 'config/production/rate-limits' }
    });

    watch.on('change', (data) => {
      try {
        const parsed = JSON.parse(data.Value);
        this.config.set('rateLimits', parsed);
        console.log('Dynamic configuration reloaded successfully.');
      } catch (err) {
        console.error('Invalid dynamic config syntax! Retaining previous safe config.');
      }
    });
  }

  static get(key: string, defaultValue: any) {
    return this.config.get(key) ?? defaultValue;
  }
}
